"""Adversarial cross-check of transitive skip, focused on the report claim:
any task with a failed-or-skipped ancestor ANYWHERE (depth >= 2) must be skipped."""
import random
from taskdag.scheduler import Scheduler

def failed_ancestor(t, deps, failed):
    """DFS: does t transitively depend on any failed task?"""
    seen = set()
    stack = list(deps.get(t, ()))
    while stack:
        u = stack.pop()
        if u in failed:
            return True
        if u in seen:
            continue
        seen.add(u)
        stack.extend(deps.get(u, ()))
    return False

random.seed(20260701)
for trial in range(5000):
    names = list("abcdefghijklm")
    g = Scheduler()
    for n in names:
        g.add_task(n)
    for _ in range(random.randint(1, 45)):
        a, b = random.choice(names), random.choice(names)
        try:
            g.add_dependency(a, b)
        except ValueError:
            pass
    order = g.topo_order()
    fail_on = {n for n in names if random.random() < 0.2}

    # Independent reference simulation over the topo order
    failed = set()
    ref, ref_calls = {}, []
    for name in order:
        if any(d in failed for d in g._deps[name]):
            ref[name] = "skipped"
            continue
        ref_calls.append(name)
        if name in fail_on:
            failed.add(name)
            ref[name] = "failed"
        else:
            ref[name] = "ok"

    calls = []
    def runner(n):
        calls.append(n)
        if n in fail_on:
            raise RuntimeError("boom")
    got = g.run(runner)

    assert got == ref, (trial, fail_on, g._deps, got, ref)
    assert calls == ref_calls, (trial, fail_on, calls, ref_calls)

    # Core claim, depth >= 2 included: nothing with a failed ancestor runs.
    for n in names:
        if got[n] == "skipped":
            assert n not in calls, (trial, n)
            assert failed_ancestor(n, g._deps, fail_on), (trial, n, fail_on, got)
        if got[n] == "ok":
            assert not failed_ancestor(n, g._deps, fail_on), (trial, n, got)
        if n in fail_on and got[n] == "failed":
            assert n in calls, (trial, n)
print("adversarial fuzz: 5000 trials, transitive skip always matches reference")
